  const notebook = Number(body?.notebook_id) || null, color = /^#[0-9a-f]{6}$/i.test(body?.color) ? body.color : "#ffffff", kind = body?.kind === "task" ? "task" : "note", taskStatus = ["active","in_progress","completed","closed","frozen","failed","retry"].includes(body?.task_status) ? body.task_status : "active";
