  let body; try { body = await request.json(); } catch { return json({ error: "صيغة الطلب غير صحيحة." }, 400); }
  const old = await getNote(env, id, userId); if (!old) return json({ error: "الملاحظة غير موجودة." }, 404);
  const title = clean(body?.title, old.title), content = clean(body?.content, old.content), notebook = body?.notebook_id === null ? null : Number(body?.notebook_id) || old.notebook_id;
  const color = /^#[0-9a-f]{6}$/i.test(body?.color) ? body.color : old.color, archived = body?.archived === undefined ? old.archived : (body.archived ? 1 : 0), kind = body?.kind === "task" || old.kind === "task" ? "task" : "note", taskStatus = ["active","in_progress","completed","closed","frozen","failed","retry"].includes(body?.task_status) ? body.task_status : (old.task_status || "active");
