  const note = await env.DB.prepare("UPDATE notes SET title=?,content=?,notebook_id=?,color=?,archived=?,kind=?,task_status=?,deleted_at=?,updated_at=datetime('now') WHERE id=? AND user_id=? RETURNING *").bind(title, content, notebook, color, archived, kind, taskStatus, deletedAt, id, userId).first();
