async function deleteNotebook(env, id, userId) { if (!Number.isInteger(id) || id < 1) return json({ error: "معرف الدفتر غير صحيح." }, 400); const row = await env.DB.prepare("SELECT name FROM notebooks WHERE id=? AND user_id=?").bind(id,userId).first(); if (!row) return json({ error: "الدفتر غير موجود." },404); if (row.name === "بدون دفتر") return json({ error: "لا يمكن حذف الدفتر الافتراضي." },400); await env.DB.prepare("UPDATE notes SET notebook_id=NULL WHERE notebook_id=? AND EXISTS (SELECT 1 FROM notes n WHERE n.id=notes.id AND n.user_id=?)").bind(id,userId).run(); await env.DB.prepare("DELETE FROM notebooks WHERE id=? AND user_id=?").bind(id,userId).run(); return json({success:true}); }
async function updateTag(request, env, id, userId) { let body; try { body = await request.json(); } catch { return json({ error: "صيغة الطلب غير صحيحة." }, 400); } const name=clean(body?.name); if (!Number.isInteger(id)||id<1||!name||name.length>40) return json({error:"بيانات العلامة غير صحيحة."},400); try { const row=await env.DB.prepare("UPDATE tags SET name=?,color=? WHERE id=? AND user_id=? RETURNING id,name,color").bind(name,/^#[0-9a-f]{6}$/i.test(body?.color)?body.color:'#2f80ed',id,userId).first(); return row?json(row):json({error:'العلامة غير موجودة.'},404); } catch { return json({error:'اسم العلامة مستخدم بالفعل.'},409); } }
