async function purgeExpiredTrash(env, userId) { const setting=await env.DB.prepare("SELECT value FROM user_settings WHERE user_id=? AND key='trash_retention_days'").bind(userId).first(); const days=Math.max(1,Math.min(3650,Number(setting?.value)||30)); const cutoff=new Date(Date.now()-days*86400000).toISOString(); await env.DB.prepare("DELETE FROM notes WHERE user_id=? AND deleted_at IS NOT NULL AND deleted_at<?").bind(userId,cutoff).run(); }
