  if (request.method === "POST" && url.pathname === "/api/auth/logout") return authLogout(request, env);
  if (request.method === "POST" && url.pathname === "/api/auth/change-password") { const user = await currentUser(request, env); return user ? changePassword(request, env, user.id) : json({ error: "تسجيل الدخول مطلوب." }, 401); }
