    if (request.method === "DELETE" && url.pathname.startsWith("/api/notes/")) { const body=await request.json().catch(()=>({})); const permanent=body?.permanent===true; const result = permanent ? await env.DB.prepare("DELETE FROM notes WHERE id=? AND user_id=?").bind(idOf(url), uid).run() : await env.DB.prepare("UPDATE notes SET deleted_at=?,updated_at=datetime('now') WHERE id=? AND user_id=?").bind(new Date().toISOString(),idOf(url), uid).run(); return result.meta.changes ? json({ success:true,permanent }) : json({ error:"الملاحظة غير موجودة." },404); }
    if (request.method === "GET" && url.pathname === "/api/notebooks") return listNotebooks(env, uid);
